    // 2026-10-18).
    if (!provider || typeof provider.latestVerdictRecord !== 'function') return null;
    return provider.latestVerdictRecord(prNumber, headSha,
        { authorLogins: machineAuthorModule.machineAuthorLogins(machineAuthor) });
}

