        // (issue-anchored rework-on-red-ci AND PR-anchored
        // rework-on-label) land the leg ON the PR branch
        // (workflowRef={branch}), and the leg is the branch's SINGLE
        // WRITER — two concurrent legs on one branch race every push
        // (live PR #1017 / gh-1000, 2026-10-18 08:04–08:09Z: TWO
        // concurrent rework legs for ONE rework cycle — the first leg's
        // push moved the head c2e0d28f → 94988905, so the gh-806
        // (pr, head) latch keyed a NEW head and never suppressed the
        // second arm, and the PR-armed factory run titled
        // 'workflow_dispatch # rework' carries no '· gh-N'/'#N' anchor
        // token, so the title guards above were blind to it). This probe
        // keys on the BRANCH, not the head: an ACTIVE ai-teammate run
        // whose head_branch IS the dispatch branch — regardless of
        // head_sha — owns the branch, and the dispatch is suppressed.
        // gh-1075 fork reroute: a rerouted fork dispatch lands on the base
        // machine ref — the run's head_branch is 'main', SHARED by every
        // fork dispatch — so the probe keys on the PR anchor instead (the
        // run-title '· pr-<N>' token the fork path always backfills; see
        // hasActiveLegRunForPull). Keying on 'main' would serialize
        // unrelated fork legs; keying on refs/pull/<N>/head matches
        // nothing (GitHub records the DISPATCH ref, not the checkout
        // plan, as head_branch).
        // The arm survives (no consumeLabels bookkeeping here, unlike
        // the gh-715 cross-anchor path): a leg that dies silently leaves
        // the arm armed, and the next quiet tick re-fires it — the
        // dead-letter recovery the machine loop is built on.
        if (headRefDispatch) {
            var legAlreadyInFlight = forkPlan.checkoutRef
                ? hasActiveLegRunForPull(scm, workflowFile, it0.prNumber)
                : hasActiveLegRunOnBranch(scm, workflowFile, it0.branch);
            if (legAlreadyInFlight) {
                var legGuardKey = forkPlan.checkoutRef
                    ? ('pr-' + it0.prNumber + ' (fork head)')
                    : ('branch ' + it0.branch);
                console.log('  ⏭️  ' + ticketKey + ' skipped (leg already in flight on ' +
                    legGuardKey + ' — gh-1028: the head is the leg\'s single writer, ' +
                    'a second leg would race its push)');
                return false;
            }
        }
        var inputs;
        if (rule.inputs) {
            // Rule-declared dispatch inputs (github-source rules): values may
            // reference the matched item via '{key}' / '{issueNumber}' /
            // '{prNumber}' placeholders.
            var it = item || {};
            // {issueNumber} on a PR-carrier item without a linked issue must
            // NOT fall back to the ticket key — dispatching issue='pr-N'
            // breaks the factory guard's anchor validation.
            var needsIssue = Object.keys(rule.inputs).some(function (k) {
                return String(rule.inputs[k]).indexOf('{issueNumber}') !== -1;
            });
            // #544: the linked issue on a PR-carrier item came from a body
            // scrape — verify it resolves to an EXISTING LOCAL issue before
            // anchoring the dispatch on it. A cross-repo/dangling ref
            // ('dm.ai #601') would 404 in the factory guard.
            var issueNumber = (it.issueNumber === undefined || it.issueNumber === null)
                ? null : it.issueNumber;
            if (needsIssue && issueNumber !== null && it.prNumber) {
                if (!localIssueExists(repoInfo, issueNumber)) {
                    console.log('  ⚠️  #' + issueNumber + ' scraped from PR #' + it.prNumber +
                        ' does not exist in ' + repoInfo.owner + '/' + repoInfo.repo +
                        ' (cross-repo or dangling ref) — not a local anchor (#544)');

