    // Array form (owner FIFO rule 2026-09-22): exclude PRs in ANY of the
    // listed states — validate-armed skips BEHIND (refresh first) AND
    // DIRTY (conflict-rework owns the oldest).
    var nmsWant = wantList(q.notMergeState);
