function _ghIsBookeepingCheck(cname) {
    for (var bi = 0; bi < BOOKKEEPING_CHECK_PREFIXES.length; bi++) {
        if (cname.indexOf(BOOKKEEPING_CHECK_PREFIXES[bi]) === 0) return true;
    }
    return false;
