        // parity) — github_merge_pr does NOT throw on a 405. Clearing the
        // markers on a refused merge orphaned fa pr-753 (logged
        // "squash-merged", PR stayed open and unarmed).
        var sm = makeSmAgent(Object.assign(config('a', 'b'), {
