                ? hasActiveLegRunForPull(scm, workflowFile, it0.prNumber)
                : hasActiveLegRunOnBranch(scm, workflowFile, it0.branch);
            if (legAlreadyInFlight) {
                var legGuardKey = forkPlan.checkoutRef
                    ? ('pr-' + it0.prNumber + ' (fork head)')
                    : ('branch ' + it0.branch);
                console.log('  ⏭️  ' + ticketKey + ' skipped (leg already in flight on ' +
                    legGuardKey + ' — gh-1028: the head is the leg\'s single writer, ' +
                    'a second leg would race its push)');
                return false;
            }
        }
        var inputs;
        if (rule.inputs) {
            // Rule-declared dispatch inputs (github-source rules): values may
            // reference the matched item via '{key}' / '{issueNumber}' /
            // '{prNumber}' placeholders.
            var it = item || {};
            // {issueNumber} on a PR-carrier item without a linked issue must
            // NOT fall back to the ticket key — dispatching issue='pr-N'
            // breaks the factory guard's anchor validation.
            var needsIssue = Object.keys(rule.inputs).some(function (k) {
                return String(rule.inputs[k]).indexOf('{issueNumber}') !== -1;
            });
