                pr: { number: 754, labels: ['pr_approved', 'ai_validating'] },
                mergeResult: 'Bad Gateway'
            }
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', rules: [RULES.merge] } });

        assert.equal(sm.capturedPrLabelRemoves.length, 0);
    });

