        assert.ok(teeAt !== -1, 'gh-1074: the chain tees its stderr to a side file');
        var chain = cmd.slice(0, teeAt);
        assert.equal(chain.slice(-'git push https://x-access-token:[REDACTED:Connection String Password]@github.com/epam/dmtools-dart.git \'feat/x\''.length),
            'git push https://x-access-token:[REDACTED:Connection String Password]@github.com/epam/dmtools-dart.git \'feat/x\'');
        // No env swap: the push rides the checkout's stored credentials.
        assert.equal(sm.capturedEnvSets.length, 0, 'no token swap');
