    if (targetTicket && targetAgent) {
        console.log('SM Agent: Targeted mode — ticket: ' + targetTicket + ', agent: ' + targetAgent);

        var matchedRule = null;
        if (rules) {
            var normalizeAgent = function(cf) { return cf ? cf.replace(/^agents\//, '') : ''; };
