    var ruleTrackerProvider = smTracker(effectiveConfig).provider();
    var interpolatedJql = configLoader.interpolateJql(
        configLoader.selectRuleQuery(rule, ruleTrackerProvider), effectiveConfig, ruleTrackerProvider);


