    test('context spelling (StatusContext) reads like name (CheckRun)', function () {
        var t = mod.realCheckTally([
            { context: 'quality', state: 'success' },
            { context: 'gate', state: 'failure' }
        ], null);
        assert.equal(t.real, 2);
        assert.equal(t.red, 1);
