        }
        if (!tickMergeReservationReleased &&
            (nextLayerIdx === null /* end of rules */
                || nextLayerIdx > smRuleLayersModule.L3_IDX)) {
            tickMergeReservationReleased = true;
            if (tickMergeReservedSlots > 0 && workflowBudget) {
                if (!tickMergeSlotSpent) {
