        var machineMerge = Array.isArray(commit.parents) && commit.parents.length >= 2 &&
            (String(commit.committer || '') === 'sm-silent-update' ||
             (!!login && machineAuthorModule.isMachineLogin(commit.login, machineAuthor)));
