function scanGuestDeadZoneTick(machineAuthor) {
    var blocked = [];
    Object.keys(tickReposSeen).forEach(function (repoKey) {
        var dzRepoInfo = tickReposSeen[repoKey];
        if (!dzRepoInfo || !dzRepoInfo.owner || !dzRepoInfo.repo) return;
