                var item = {
                    prNumber: p && (p.number || p.prNumber),
                    labels: ((p && p.labels) || []).map(function (l) {
                        return (l && l.name) || l;
                    }),
                    author: (p && ((p.user && p.user.login) || p.author)) || ''
