            },
            onCliExecute: cliRouter({ events: armEventJson('yury-by'),
                                      headRuns: '{"workflow_runs":[]}' })
        }));
        sm.action({ jobParams: { owner: 'isti', repo: 'harness',
            machineAuthor: 'ai-teammate', rules: [GUEST_MERGE] } });

