    test('mergeableZeroFailing: stub-only head merges, red and real-pending do not', function () {
        assert.equal(mod.mergeableZeroFailing(mod.realCheckTally([
            { name: 'merge / 1', status: 'COMPLETED', conclusion: 'SKIPPED' }
